arguments.command:
python3 -c "
import hmac, hashlib, base64, json

def b64url_encode(data):
    if isinstance(data, str):
        data = data.encode()
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode()

# Create a simple valid HS256 token for testing
header = {'alg': 'HS256', 'typ': 'JWT'}
payload = {'sub': 'user1', 'role': 'admin'}
h = b64url_encode(json.dumps(header, separators=(',', ':')))
p = b64url_encode(json.dumps(payload, separators=(',', ':')))
sig = hmac.new(b'testsecret', (h + '.' + p).encode(), hashlib.sha256).digest()
s = b64url_encode(sig)
print(f'{h}.{p}.{s}')
" 2>&1 | tee /tmp/test_token.txt

